def predict(probe):
    # f(x) = 16.4*x - 2.5 for x > 0   [E1,E3,E5,E7,E8,E9,E10,E11]
    # f(x) = -8.2*x + 2.5 for x < 0   [E1,E2,E4,E5,E7,E8,E9,E10,E11]
    # f(0) = 2.5                       [E2,E4,E6]
    # discontinuity at 0: left limit 2.5, right limit -2.5 [E6]
    out = []
    for x in probe.get("x", []):
        if x is None:
            out.append(None)
            continue
        if x > 0:
            y = 16.4 * x - 2.5
        elif x < 0:
            y = -8.2 * x + 2.5
        else:
            y = 2.5
        out.append(round(y, 6))
    return {"y": out}
